18	export function createWebhookDispatcher({
19	  retryDelaysMs = DEFAULT_RETRY_DELAYS_MS,
20	  log = () => {},
21	} = {}) {
22	  const pending = new Set();
23	  let generation = 0;
24	
25	  async function attempt(webhook, rawBody, signature) {
26	    try {
27	      const response = await fetch(webhook.url, {
28	        method: "POST",
29	        headers: {
30	          "Content-Type": "application/json",
31	          "User-Agent": "Parcelly-Webhooks/1.0",
32	          [SIGNATURE_HEADER]: signature,
33	        },
34	        body: rawBody,
35	        signal: AbortSignal.timeout(ATTEMPT_TIMEOUT_MS),
36	      });
37	      return response.ok;
38	    } catch {
39	      return false;
40	    }
41	  }
