43	  async function deliver(webhook, event, startedIn) {
44	    const rawBody = JSON.stringify(event);
45	    const signature = signPayload(webhook.secret, rawBody);
46	    for (let index = 0; index <= retryDelaysMs.length; index += 1) {
47	      if (index > 0) {
48	        await sleep(retryDelaysMs[index - 1]);
49	      }
50	      if (generation !== startedIn) {
51	        return;
52	      }
53	      if (await attempt(webhook, rawBody, signature)) {
54	        return;
55	      }
56	    }
57	    log(`webhook ${event.event} for ${event.shipment_id} not delivered to ${webhook.url}`);
58	  }
59	
60	  return {
61	    dispatch(webhook, event) {
62	      const task = deliver(webhook, event, generation).finally(() => pending.delete(task));
63	      pending.add(task);
